  if (!this.rpcProcess) return 0;
  const result = await this.executeViaRpc("end_background", {}, { ignoreTurnSignal: true });
  try {
    return Number(JSON.parse(result?.output ?? "{}").ended ?? 0);
  } catch {
    return 0;
  }
