5985	    // A run_tests result is a verifier attempt on the current workspace (what a requirement's `verified` rests on).
5986	    if (toolName === "run_tests" && this.objective && this.durable) {
5987	      try {
5988	        const parsed = JSON.parse(receipt.output || "{}");
