private saveTaskStateLocked(state: DurableTaskState, workspacePaths: WorkspacePath[], options: { historical?: boolean } = {}): DurableTaskState {
  if (!state.taskId) {
    throw new TaskStateWriteError("unknown", "Missing required taskId");
