    turn.phase = "tool";
    turn.currentTool = toolName;
    const { receipt, shouldExit } = await this.dispatchToolCall(
      call,
      currentStep,
      "agent",
      onConfirm
    );
    turn.currentTool = undefined;
    observe(call, receipt, reacquire);

    let finalContent = receipt.success
      ? receipt.output
