11	  defaultRegistry,
12	  CapabilityHandler,
13	  changesWorkspace,
14	} from "./capabilities.js";
15	
16	export interface InvocationRequest {
17	  /** Unique invocation identity (assigned if omitted) (EXEC-002) */
18	  invocationId?: string;
19	  /** Owning task identity (EXEC-002) */
20	  taskId?: string;
21	  /** Actor identity requesting invocation (ACT-001..004, EXEC-008) */
22	  actor?: "agent" | "subagent" | "operator" | "extension" | string;
23	  /** Execution domain in effect (EXEC-013) */
24	  executionDomain?: "agent_orchestration" | "operator_direct_shell" | "subagent" | "extension" | string;
25	  /** Model-visible tool name */
26	  toolName: string;
27	  /** Invocation arguments */
28	  args: Record<string, any>;
29	  /** Step index in active turn */
30	  stepIndex?: number;
31	}
32	
33	export interface InvocationContext {
34	  /** Effective verified workspace or worktree root path (EXEC-003) */
35	  workspaceRoot: string;
36	  /** Dry-run simulation mode flag */
37	  dryRun?: boolean;
38	  /** Read-only mode flag */
39	  readOnly?: boolean;
40	  /** Custom metadata */
41	  metadata?: Record<string, any>;
42	  /** RustCoreBridge instance if available */
43	  bridge?: any;
44	  /** Fallback default execution handler */
45	  defaultHandler?: (
46	    toolName: string,
47	    args: Record<string, any>,
48	    context: InvocationContext
49	  ) => Promise<ExecutionResult>;
50	  [key: string]: any;
51	}
52	
53	export interface AdmissionDecision {
54	  admitted: boolean;
55	  reason?: string;
56	  effectiveScope?: string;
57	}
58	
59	export interface ResourceConfinementDecision {
60	  confined: boolean;
61	  reason?: string;
62	  normalizedPath?: string;
63	}
64	
