72	export interface ProcessLifecycleEvent {
73	  stage: "start" | "exit" | "cancel" | "timeout";
74	  invocationId: string;
75	  toolName: string;
76	  command?: string;
77	  pid?: number;
78	  exitCode?: number;
79	  error?: string;
80	}
