95	export interface ExecutionReceipt {
96	  /** Immutable invocation identity (EXEC-002) */
97	  invocationId: string;
98	  /** Owning task identity (EXEC-002) */
99	  taskId: string;
100	  /** Actor identity (EXEC-008, EVID-003) */
101	  actor: string;
102	  /** Execution domain (EXEC-013, EVID-003) */
103	  executionDomain: string;
104	  /** Canonical capability identity (CAP-001) */
105	  capabilityId: string;
106	  /** Model-visible tool name */
107	  toolName: string;
108	  /** Concrete affected or queried resource paths/targets (CAP-004) */
109	  targetResources: string[];
110	  /** Outcome status */
111	  success: boolean;
112	  /** Execution output string */
113	  output: string;
114	  /** Error message if failed or denied */
115	  error?: string;
116	  /** Execution duration in milliseconds */
117	  durationMs: number;
118	  /** Whether candidate state was mutated by operation (CAND-001) */
119	  candidateMutated: boolean;
120	  /** High-level execution status */
121	  status: "COMPLETED" | "DENIED" | "FAILED" | "BLOCKED";
122	  /** Typed denial reason if status is DENIED */
123	  denialReason?: string;
124	  /** ISO 8601 timestamp (EVID-003) */
125	  timestamp: string;
126	  /** Whether operation was simulated rather than actual host effect (EXEC-010) */
127	  simulated: boolean;
128	}
