130	/**
131	 * The 7 Upfront Hook Interfaces for Downstream Increments (F-09)
132	 */
133	export type AuthorityAdmissionHook = (
134	  request: InvocationRequest,
135	  context: InvocationContext
136	) => Promise<AdmissionDecision>;
137	
138	export type ResourceConfinementHook = (
139	  request: InvocationRequest,
140	  context: InvocationContext
