148	export type ProcessLifecycleHook = (
149	  event: ProcessLifecycleEvent,
150	  context: InvocationContext
151	) => Promise<void>;
152	
153	export type CandidateMutationHook = (
154	  event: CandidateMutationEvent,
155	  context: InvocationContext
156	) => Promise<void>;
157	
158	export type ContextAdmissionHook = (
159	  request: InvocationRequest,
160	  context: InvocationContext
161	) => Promise<ContextAdmissionDecision>;
162	
163	export type EvidenceEmissionHook = (
164	  receipt: ExecutionReceipt
165	) => Promise<void>;
166	
167	export interface SpineHooks {
168	  authorityAdmission?: AuthorityAdmissionHook;
169	  resourceConfinement?: ResourceConfinementHook;
170	  egressQuarantine?: EgressQuarantineHook;
171	  processLifecycle?: ProcessLifecycleHook;
172	  candidateMutation?: CandidateMutationHook;
173	  contextAdmission?: ContextAdmissionHook;
174	  evidenceEmission?: EvidenceEmissionHook;
175	}
176	
177	export interface SpineOptions {
178	  registry?: CapabilityRegistry;
179	  hooks?: SpineHooks;
180	}
181	
182	export const DEFAULT_SPINE_HOOKS: Required<SpineHooks> = {
183	  authorityAdmission: async () => ({ admitted: true }),
184	  resourceConfinement: async () => ({ confined: true }),
185	  egressQuarantine: async (req) => ({ allowed: true, sanitizedArgs: req.args }),
186	  processLifecycle: async () => {},
187	  candidateMutation: async () => {},
188	  contextAdmission: async () => ({ admitted: true }),
189	  evidenceEmission: async () => {},
190	};
191	
192	export function extractTargetResources(
193	  _toolName: string,
194	  args: Record<string, any>
195	): string[] {
196	  const resources: string[] = [];
197	  if (!args || typeof args !== "object") return resources;
198	
199	  if (typeof args.path === "string" && args.path) {
200	    resources.push(args.path);
201	  }
202	  if (Array.isArray(args.paths)) {
203	    for (const p of args.paths) {
204	      if (typeof p === "string" && p) resources.push(p);
205	    }
206	  }
207	  if (typeof args.target_file === "string" && args.target_file) {
208	    resources.push(args.target_file);
209	  }
210	  if (typeof args.file_path === "string" && args.file_path) {
211	    resources.push(args.file_path);
212	  }
213	  if (typeof args.url === "string" && args.url) {
214	    resources.push(args.url);
215	  }
216	  if (typeof args.output_path === "string" && args.output_path) {
217	    resources.push(args.output_path);
218	  }
219	  if (typeof args.command === "string" && args.command) {
220	    resources.push(args.command);
221	  }
222	  return resources;
223	}
224	
225	function validateToolArguments(
226	  capability: CanonicalCapability,
227	  args: Record<string, any>
228	): { valid: boolean; error?: string } {
229	  if (!args || typeof args !== "object" || Array.isArray(args)) {
230	    return { valid: false, error: "Tool arguments must be a JSON object." };
231	  }
232	  const required = capability.toolDefinition.function.parameters.required;
233	  if (Array.isArray(required)) {
234	    for (const reqKey of required) {
235	      if (args[reqKey] === undefined || args[reqKey] === null) {
236	        return {
237	          valid: false,
238	          error: `Missing required parameter '${reqKey}' for tool '${capability.modelToolName}'.`,
239	        };
240	      }
241	    }
242	  }
243	  return { valid: true };
244	}
245	
246	export class ExecutionSpine {
247	  private readonly registry: CapabilityRegistry;
248	  private readonly hooks: Required<SpineHooks>;
249	  private readonly handlers = new Map<string, CapabilityHandler>();
250	
251	  constructor(options: SpineOptions = {}) {
252	    this.registry = options.registry || defaultRegistry;
253	    this.hooks = {
254	      authorityAdmission:
255	        options.hooks?.authorityAdmission || DEFAULT_SPINE_HOOKS.authorityAdmission,
256	      resourceConfinement:
257	        options.hooks?.resourceConfinement || DEFAULT_SPINE_HOOKS.resourceConfinement,
258	      egressQuarantine:
259	        options.hooks?.egressQuarantine || DEFAULT_SPINE_HOOKS.egressQuarantine,
260	      processLifecycle:
261	        options.hooks?.processLifecycle || DEFAULT_SPINE_HOOKS.processLifecycle,
262	      candidateMutation:
263	        options.hooks?.candidateMutation || DEFAULT_SPINE_HOOKS.candidateMutation,
264	      contextAdmission:
265	        options.hooks?.contextAdmission || DEFAULT_SPINE_HOOKS.contextAdmission,
266	      evidenceEmission:
267	        options.hooks?.evidenceEmission || DEFAULT_SPINE_HOOKS.evidenceEmission,
268	    };
269	  }
270	
271	  public getRegistry(): CapabilityRegistry {
272	    return this.registry;
273	  }
274	
275	  public getHooks(): Required<SpineHooks> {
276	    return { ...this.hooks };
277	  }
278	
279	  public setHook<K extends keyof SpineHooks>(hookName: K, hook: SpineHooks[K]): void {
280	    if (hook) {
281	      this.hooks[hookName] = hook as any;
282	    }
283	  }
284	
285	  public registerHandler(toolName: string, handler: CapabilityHandler): void {
286	    this.handlers.set(toolName, handler);
287	  }
288	
289	  public getHandler(toolName: string): CapabilityHandler | undefined {
290	    return this.handlers.get(toolName);
291	  }
292	
293	  /**
294	   * Execute an invocation request through the unified 6-stage execution spine.
295	   * Every execution path dispatches through this pipeline, emitting an execution receipt.
296	   */
297	  public async execute(
298	    request: InvocationRequest,
299	    context: InvocationContext
300	  ): Promise<ExecutionReceipt> {
301	    const invocationId = request.invocationId || randomUUID();
302	    const taskId = request.taskId || "task-default";
303	    const actor = request.actor || "agent";
304	    const executionDomain = request.executionDomain || "agent_orchestration";
305	    const toolName = request.toolName;
306	    const targetResources = extractTargetResources(toolName, request.args || {});
307	
308	    // Stage 1: Request Ingestion & Normalization
309	    const capability = this.registry.getByToolName(toolName);
310	    if (!capability) {
311	      const receipt: ExecutionReceipt = {
312	        invocationId,
313	        taskId,
314	        actor,
315	        executionDomain,
316	        capabilityId: "unregistered",
317	        toolName,
318	        targetResources,
319	        success: false,
320	        output: "",
321	        error: `FAIL-001: Tool '${toolName}' is not registered in CapabilityRegistry.`,
322	        durationMs: 0,
323	        candidateMutated: false,
324	        status: "FAILED",
325	        timestamp: new Date().toISOString(),
326	        simulated: Boolean(context.dryRun),
327	      };
328	      await this.hooks.evidenceEmission(receipt);
329	      return receipt;
330	    }
331	
332	    const argValidation = validateToolArguments(capability, request.args || {});
333	    if (!argValidation.valid) {
334	      const receipt: ExecutionReceipt = {
335	        invocationId,
336	        taskId,
337	        actor,
338	        executionDomain,
339	        capabilityId: capability.id,
340	        toolName,
341	        targetResources,
342	        success: false,
343	        output: "",
344	        error: `FAIL-002: Malformed arguments: ${argValidation.error}`,
345	        durationMs: 0,
346	        candidateMutated: false,
347	        status: "FAILED",
348	        timestamp: new Date().toISOString(),
349	        simulated: Boolean(context.dryRun),
350	      };
351	      await this.hooks.evidenceEmission(receipt);
352	      return receipt;
353	    }
354	
355	    // Stage 2: Context & Admission Gate
356	    try {
357	      const contextDecision = await this.hooks.contextAdmission(request, context);
358	      if (!contextDecision.admitted) {
359	        const receipt: ExecutionReceipt = {
360	          invocationId,
361	          taskId,
362	          actor,
363	          executionDomain,
364	          capabilityId: capability.id,
365	          toolName,
366	          targetResources,
367	          success: false,
368	          output: "",
369	          error: contextDecision.reason || "Context admission gate denied invocation.",
370	          durationMs: 0,
371	          candidateMutated: false,
372	          status: "DENIED",
373	          timestamp: new Date().toISOString(),
374	          simulated: Boolean(context.dryRun),
375	        };
376	        await this.hooks.evidenceEmission(receipt);
377	        return receipt;
378	      }
379	    } catch (err: any) {
380	      const receipt: ExecutionReceipt = {
381	        invocationId,
382	        taskId,
383	        actor,
384	        executionDomain,
385	        capabilityId: capability.id,
386	        toolName,
387	        targetResources,
388	        success: false,
389	        output: "",
390	        error: `FAIL-001: Context admission exception: ${err.message}`,
391	        durationMs: 0,
392	        candidateMutated: false,
393	        status: "FAILED",
394	        timestamp: new Date().toISOString(),
395	        simulated: Boolean(context.dryRun),
396	      };
397	      await this.hooks.evidenceEmission(receipt);
398	      return receipt;
399	    }
400	
401	    // Stage 3: Authority & Resource Gate
402	    try {
403	      const authorityDecision = await this.hooks.authorityAdmission(request, context);
404	      if (!authorityDecision.admitted) {
405	        const receipt: ExecutionReceipt = {
406	          invocationId,
407	          taskId,
408	          actor,
409	          executionDomain,
410	          capabilityId: capability.id,
411	          toolName,
412	          targetResources,
413	          success: false,
414	          output: "",
415	          error: authorityDecision.reason || "Authority admission gate denied invocation.",
416	          durationMs: 0,
417	          candidateMutated: false,
418	          status: "DENIED",
419	          timestamp: new Date().toISOString(),
420	          simulated: Boolean(context.dryRun),
421	        };
422	        await this.hooks.evidenceEmission(receipt);
423	        return receipt;
424	      }
425	
426	      const confinementDecision = await this.hooks.resourceConfinement(request, context);
427	      if (!confinementDecision.confined) {
428	        const receipt: ExecutionReceipt = {
429	          invocationId,
430	          taskId,
431	          actor,
432	          executionDomain,
433	          capabilityId: capability.id,
434	          toolName,
435	          targetResources,
436	          success: false,
437	          output: "",
438	          error: confinementDecision.reason || "Resource confinement gate blocked invocation.",
439	          durationMs: 0,
440	          candidateMutated: false,
441	          status: "BLOCKED",
442	          timestamp: new Date().toISOString(),
443	          simulated: Boolean(context.dryRun),
444	        };
445	        await this.hooks.evidenceEmission(receipt);
446	        return receipt;
447	      }
448	    } catch (err: any) {
449	      const receipt: ExecutionReceipt = {
450	        invocationId,
451	        taskId,
452	        actor,
453	        executionDomain,
454	        capabilityId: capability.id,
455	        toolName,
456	        targetResources,
457	        success: false,
458	        output: "",
459	        error: `FAIL-001: Authority/Resource gate exception: ${err.message}`,
460	        durationMs: 0,
461	        candidateMutated: false,
462	        status: "FAILED",
463	        timestamp: new Date().toISOString(),
464	        simulated: Boolean(context.dryRun),
465	      };
466	      await this.hooks.evidenceEmission(receipt);
467	      return receipt;
468	    }
469	
470	    // Stage 4: Pre-Execution Hooks
471	    let effectiveArgs = request.args;
472	    try {
473	      const egressDecision = await this.hooks.egressQuarantine(request, context);
474	      if (!egressDecision.allowed) {
475	        const receipt: ExecutionReceipt = {
476	          invocationId,
477	          taskId,
478	          actor,
479	          executionDomain,
480	          capabilityId: capability.id,
481	          toolName,
482	          targetResources,
483	          success: false,
484	          output: "",
485	          error: egressDecision.reason || "Egress quarantine gate blocked invocation.",
486	          durationMs: 0,
487	          candidateMutated: false,
488	          status: "DENIED",
489	          timestamp: new Date().toISOString(),
490	          simulated: Boolean(context.dryRun),
491	        };
492	        await this.hooks.evidenceEmission(receipt);
493	        return receipt;
494	      }
495	      if (egressDecision.sanitizedArgs) {
496	        effectiveArgs = egressDecision.sanitizedArgs;
497	      }
498	
499	      await this.hooks.processLifecycle(
500	        {
501	          stage: "start",
502	          invocationId,
503	          toolName,
504	          command: effectiveArgs.command,
505	        },
506	        context
507	      );
508	    } catch (err: any) {
509	      const receipt: ExecutionReceipt = {
510	        invocationId,
511	        taskId,
512	        actor,
513	        executionDomain,
514	        capabilityId: capability.id,
515	        toolName,
516	        targetResources,
517	        success: false,
518	        output: "",
519	        error: `FAIL-001: Pre-execution hook exception: ${err.message}`,
520	        durationMs: 0,
521	        candidateMutated: false,
522	        status: "FAILED",
523	        timestamp: new Date().toISOString(),
524	        simulated: Boolean(context.dryRun),
525	      };
526	      await this.hooks.evidenceEmission(receipt);
527	      return receipt;
528	    }
529	
530	    // Stage 5: Capability Dispatch
531	    const t0 = Date.now();
532	    let result: ExecutionResult;
533	    try {
534	      const handler =
535	        this.handlers.get(toolName) ||
536	        this.registry.getHandler(toolName) ||
537	        capability.handler;
538	
539	      if (handler) {
540	        result = await handler(effectiveArgs, context);
541	      } else if (context.defaultHandler) {
542	        result = await context.defaultHandler(toolName, effectiveArgs, context);
543	      } else if (context.bridge && typeof context.bridge.executeTool === "function") {
544	        result = await context.bridge.executeTool(toolName, effectiveArgs, context.metadata?.verificationAuthority);
545	      } else {
546	        result = {
547	          success: false,
548	          output: "",
549	          error: `No execution handler registered for capability '${capability.id}' (tool '${toolName}').`,
550	        };
551	      }
552	    } catch (err: any) {
553	      result = {
554	        success: false,
555	        output: "",
556	        error: `FAIL-001: Invocation exception in '${toolName}': ${err?.message || String(err)}`,
557	      };
558	    }
559	    const durationMs = Date.now() - t0;
560	
561	    try {
562	      await this.hooks.processLifecycle(
563	        {
564	          stage: "exit",
565	          invocationId,
566	          toolName,
567	          exitCode: result.success ? 0 : 1,
568	          error: result.error,
569	        },
570	        context
571	      );
572	    } catch {
573	      // Degraded-mode per FAIL-003: lifecycle notification error does not overwrite tool outcome
574	    }
575	
576	    // Stage 6: Post-Execution Evidence & Receipt Generation
577	    const candidateMutated = Boolean(
578	      result.success && changesWorkspace(capability) && !context.dryRun
579	    );
580	
581	    if (candidateMutated) {
582	      try {
583	        await this.hooks.candidateMutation(
584	          {
585	            invocationId,
586	            toolName,
587	            mutatedPaths: targetResources,
588	            durationMs,
589	          },
590	          context
591	        );
592	      } catch {
593	        // Degraded-mode per FAIL-003
594	      }
595	    }
596	
597	    const receipt: ExecutionReceipt = {
598	      invocationId,
599	      taskId,
600	      actor,
601	      executionDomain,
602	      capabilityId: capability.id,
603	      toolName,
604	      targetResources,
605	      success: result.success,
606	      output: result.output || "",
607	      error: result.error,
608	      durationMs,
609	      candidateMutated,
610	      status: result.success ? "COMPLETED" : result.denialReason ? "DENIED" : "FAILED",
611	      ...(result.denialReason ? { denialReason: result.denialReason } : {}),
612	      timestamp: new Date().toISOString(),
613	      simulated: Boolean(context.dryRun),
614	    };
615	
616	    try {
617	      await this.hooks.evidenceEmission(receipt);
618	    } catch {
619	      // Degraded-mode per FAIL-003
620	    }
621	
622	    return receipt;
623	  }
624	}
