134	    // Recreating from baseCommit would silently drop every integrated unit; only the operator can restore it.
135	    throw new Error(
136	      "the integration branch and worktree are gone but this operation already integrated work; restore the branch or start a new operation",
137	    );
138	  }
139	  ensureGitExclude(plan.repoRoot);
140	  fs.mkdirSync(plan.baseDir, { recursive: true });
141	  // A missing worktree with the branch still present is repaired in place (the branch is the source of truth).
142	  gitResult(plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
