    gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
    let added = add();
    if (!added.ok && /already registered|missing but already registered/i.test(added.stderr)) {
      gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
      gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
      added = add();
