        kind: "nothing",
        receipt: {
          unitId: unit.id,
          branch: entry.branch,
          commit: entry.integratedCommit,
          integratedCommit: entry.integratedCommit,
          mergedAt: new Date().toISOString(),
          files: [],
          outcome: result.outcome,
          summary: result.summary,
          verification: "ALREADY_INTEGRATED",
