37	    this.workspace = WorkspacePath.fromSelectedWorkspace(path.resolve(workspace));
38	    this.manager = new DurableStateManager({ ...(baseDir ? { baseDir } : {}), workspacePaths: [this.workspace] });
39	    this.accountIdentityHome = accountIdentityHome;
40	  }
41	
42	  private preflightFutureVersion(id: string): void {
43	    const version = this.manager.readRawOperationSchemaVersion(id);
44	    if (typeof version === "number" && Number.isInteger(version) && version > CURRENT_OPERATION_SCHEMA_VERSION) {
45	      throw new UnsupportedOperationSchemaError(version);
46	    }
47	  }
48	
49	  save(op: DurableOperationState): void {
50	    this.preflightFutureVersion(op.id);
51	    op = migrateLegacyAccountIdentities(op, createOperationAccountIdentity(this.accountIdentityHome));
52	    const existing = this.manager.hasTaskState(op.id) ? this.manager.loadTaskState(op.id) : undefined;
53	    // A newer operation document is never overwritten by an older build. Writing over it would destroy the only copy
54	    // a later build can read, which is exactly what the load gate refuses to do.
55	    const onDisk = existing?.operation?.schemaVersion;
56	    if (typeof onDisk === "number" && onDisk > CURRENT_OPERATION_SCHEMA_VERSION) throw new UnsupportedOperationSchemaError(onDisk);
57	    // A v1.0.0 operation document is upgraded by this write. Keep the record this build cannot re-create, once,
58	    // before the first v2 write, so an operator can diff or restore it. The envelope's own migration backup is a
59	    // different file and a different concern.
60	    if (existing?.operation && needsMigrationBackup(onDisk)) {
61	      this.backupBeforeMigration(op.id, typeof onDisk === "number" ? onDisk : LEGACY_OPERATION_SCHEMA_VERSION);
62	    }
63	    const state: DurableTaskState = {
64	      schemaVersion: 1,
65	      taskId: op.id,
66	      sessionId: op.id,
67	      id: op.id,
68	      title: `Operation: ${op.objective.slice(0, 80)}`,
69	      workspacePath: this.workspace.value,
70	      workspace: this.workspace.value,
71	      createdAt: existing?.createdAt ?? op.createdAt,
72	      updatedAt: op.updatedAt,
73	      status: LIFECYCLE[op.status],
74	      activePlan: op.units.map((u) => ({ name: u.title, status: u.status === "COMPLETE" ? "completed" : u.status === "RUNNING" ? "in_progress" : "pending", detail: u.status })),
75	      milestones: existing?.milestones ?? [],
76	      validationReceipts: [],
77	      messages: [],
78	      currentOperation: null,
79	      operation: op,
80	    };
81	    this.manager.saveTaskState(state, [this.workspace]);
82	  }
83	
84	  load(id: string): DurableOperationState {
85	    this.preflightFutureVersion(id);
86	    const state = this.manager.loadTaskState(id, this.workspace.value, [this.workspace]);
87	    if (!state.operation) throw new Error(`Task ${id} is not an operation`);
88	    let migrated: DurableOperationState;
89	    try {
90	      migrated = migrateOperationState(state.operation);
91	    } catch (error) {
92	      if (!(error instanceof InvalidOperationStateError)) throw error;
93	      // Structurally invalid is the operation-document analogue of an unparseable envelope: quarantine it and report
94	      // where it went, rather than leaving a record that will keep failing every later load.
95	      const quarantined = this.manager.quarantineFile(this.manager.getStateFilePath(id));
96	      throw new Error(`Operation ${id} is invalid: ${error.message} (quarantined to ${quarantined})`);
97	    }
98	    return migrateLegacyAccountIdentities(migrated, createOperationAccountIdentity(this.accountIdentityHome));
99	  }
100	
101	  /** Replay-only read: migrate and protect in memory under the store guard, never publish or quarantine the record. */
102	  loadForReplay(id: string): DurableOperationState {
103	    return withStateStoreGuard(this.manager.getBaseDir(), () => {
104	      const raw = JSON.parse(fs.readFileSync(this.manager.getStateFilePath(id), "utf8"));
105	      if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error(`Task ${id} is invalid`);
106	      const version = raw.schemaVersion ?? 0;
107	      if (typeof version === "number" && Number.isInteger(version) && version > CURRENT_STATE_SCHEMA_VERSION) {
108	        throw new UnsupportedSchemaVersionError(version);
109	      }
110	      if (!raw.operation) throw new Error(`Task ${id} is not an operation`);
111	      const opVersion = raw.operation.schemaVersion;
112	      if (typeof opVersion === "number" && Number.isInteger(opVersion) && opVersion > CURRENT_OPERATION_SCHEMA_VERSION) {
113	        throw new UnsupportedOperationSchemaError(opVersion);
114	      }
115	      const protectedRecord = redactTaskStateForPersistence(raw as DurableTaskState, [this.workspace]);
116	      return migrateOperationState(protectedRecord.operation);
117	    });
118	  }
119	
120	  /** Replay-only listing with the same no-publication guarantee as loadForReplay. */
121	  listForReplay(): DurableOperationState[] {
122	    const ids = withStateStoreGuard(this.manager.getBaseDir(), () =>
123	      fs.readdirSync(this.manager.getBaseDir())
124	        .filter((name) => name.endsWith(".json"))
125	        .map((name) => name.slice(0, -".json".length)),
126	    );
127	    const out: DurableOperationState[] = [];
128	    for (const id of ids) {
129	      try {
130	        out.push(this.loadForReplay(id));
131	      } catch (error) {
132	        if (error instanceof UnsupportedOperationSchemaError || error instanceof UnsupportedSchemaVersionError) throw error;
133	      }
134	    }
135	    return out;
136	  }
137	
138	  /** Status/export callers migrate legacy IDs on disk only when they can hold the operation lock. */
139	  loadForInspection(id: string): DurableOperationState {
140	    let release: (() => void) | undefined;
141	    try {
142	      release = this.acquire(id);
143	    } catch (error) {
144	      if (!(error instanceof OperationLockedError)) throw error;
145	    }
146	    try {
147	      const operation = this.load(id);
148	      if (release) this.save(operation);
149	      return operation;
150	    } finally {
151	      release?.();
152	    }
153	  }
154	
155	  list(): DurableOperationState[] {
156	    const out: DurableOperationState[] = [];
157	    for (const t of this.manager.listTasks()) {
158	      if (!t.title.startsWith("Operation: ")) continue;
159	      try {
160	        out.push(this.load(t.taskId));
161	      } catch (error) {
162	        // A record from a newer build is a real condition the operator must see, not a record to skip silently.
163	        if (error instanceof AccountIdentityError || error instanceof UnsupportedOperationSchemaError) throw error;
164	      }
165	    }
166	    return out;
167	  }
168	
169	  /** Status/export listing persists each legacy migration only when its operation lock is available. */
170	  listForInspection(): DurableOperationState[] {
171	    const out: DurableOperationState[] = [];
172	    for (const task of this.manager.listTasks()) {
173	      if (!task.title.startsWith("Operation: ")) continue;
174	      try {
175	        out.push(this.loadForInspection(task.taskId));
176	      } catch (error) {
177	        if (error instanceof AccountIdentityError || error instanceof UnsupportedOperationSchemaError) throw error;
178	      }
179	    }
180	    return out;
181	  }
182	
183	  /**
184	   * One driver per operation: a second process resuming it would execute its units twice. The lock names the
185	   * holder's pid; a lock whose holder on this host is gone is stale and taken over, and so is an unreadable lock
186	   * untouched for OPERATION_LOCK_UNREADABLE_GRACE_MS (its holder died mid-write). Takeover is serialised through a
187	   * kernel-owned guard and unlinks only the file that was judged stale, so two resumers cannot both take it.
188	   * Returns the release function.
189	   * Assumptions: the unreadable-lock rule compares the lock file's mtime with this process's clock, so it holds on one
190	   * host and one filesystem (NFS, or clock skew beyond the grace, can take a live lock over early). The stale takeover
191	   * depends on the `flock` utility (/usr/bin/flock); without it a stale lock fails closed with a manual-removal message.
192	   */
193	  acquire(id: string): () => void {
194	    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
195	    const create = () => fs.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, host: os.hostname(), at: new Date().toISOString() }), { flag: "wx" });
196	    const locked = (holder: { pid?: number; host?: string }) =>
197	      new OperationLockedError(`Operation ${id} is already being driven by pid ${holder.pid ?? "?"} on ${holder.host ?? "?"} (lock ${lockPath}).`);
198	    try {
199	      create();
200	    } catch (err: any) {
201	      if (err?.code !== "EEXIST") throw err;
202	      const judged = this.judgeLock(lockPath);
203	      if (!judged.stale) throw locked(judged.holder);
204	      let guard: FileGuard | null;
205	      try {
206	        guard = acquireFileGuard(`${lockPath}.reclaim`, { label: "Operation lock reclaim guard" });
207	      } catch (guardError) {
208	        throw new OperationLockedError(`Operation ${id} has a stale lock at ${lockPath} that cannot be taken over safely here (${(guardError as Error).message}); remove it by hand once no nexus command is using this workspace.`);
209	      }
210	      if (!guard) throw locked(judged.holder);
211	      try {
212	        operationLockSeams.afterStaleCheck?.();
213	        const now = this.judgeLock(lockPath, false);
214	        if (!now.stale || now.ino !== judged.ino || now.mtimeNs !== judged.mtimeNs) throw locked(now.holder);
215	        fs.unlinkSync(lockPath);
216	        try {
217	          create();
218	        } catch (createError: any) {
219	          if (createError?.code === "EEXIST") throw locked({});
220	          throw createError;
221	        }
222	      } finally {
223	        releaseFileGuard(guard);
224	      }
225	    }
226	    return () => {
227	      try {
228	        if (JSON.parse(fs.readFileSync(lockPath, "utf-8")).pid === process.pid) fs.rmSync(lockPath, { force: true });
229	      } catch {
230	        reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_release_failed");
231	      }
232	    };
233	  }
234	
235	  private judgeLock(lockPath: string, report = true): { stale: boolean; holder: { pid?: number; host?: string; at?: string }; ino?: bigint; mtimeNs?: bigint } {
236	    let stat: fs.BigIntStats;
237	    try {
238	      stat = fs.lstatSync(lockPath, { bigint: true });
239	    } catch {
240	      return { stale: false, holder: {} };
241	    }
242	    let holder: { pid?: number; host?: string; at?: string } | undefined;
243	    try {
244	      const parsed = JSON.parse(fs.readFileSync(lockPath, "utf-8"));
245	      if (parsed && typeof parsed === "object") holder = parsed;
246	    } catch {
247	      if (report) reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_read_failed");
248	    }
249	    const identity = { ino: stat.ino, mtimeNs: stat.mtimeNs };
250	    if (!holder) return { stale: Date.now() - Number(stat.mtimeNs / 1_000_000n) > OPERATION_LOCK_UNREADABLE_GRACE_MS, holder: {}, ...identity };
251	    // A lock written before this host last booted is stale even if its pid has since been reused.
252	    const beforeBoot = holder.at !== undefined && Date.parse(holder.at) < Date.now() - os.uptime() * 1000;
253	    const stale = holder.host === os.hostname() && (beforeBoot || holder.pid === undefined || !processAlive(holder.pid));
254	    return { stale, holder, ...identity };
255	  }
256	
257	  /** Most recently updated operation in this workspace that is waiting or running (to resume after restart). */
258	  latestResumable(): DurableOperationState | undefined {
259	    return this.list().find((op) => op.status === "WAITING" || op.status === "RUNNING");
260	  }
261	
262	  /**
263	   * Keeps the record this build is about to upgrade, once. Refuses to overwrite an existing copy whose bytes differ:
264	   * an earlier migration already produced it, and silently replacing it would destroy the only v1 evidence.
265	   */
266	  private backupBeforeMigration(id: string, fromVersion: unknown): void {
267	    const record = path.join(this.manager.getBaseDir(), `${id}.json`);
268	    const backup = `${record}.pre-migration-v${String(fromVersion)}`;
269	    let bytes: Buffer;
270	    try {
271	      bytes = fs.readFileSync(record);
272	    } catch (error: any) {
273	      // The record was just read to decide this backup was needed; its absence is a real problem, not a reason to skip.
274	      throw new Error(`Operation ${id}: cannot read ${record} to keep a pre-migration copy (${String(error?.message ?? error)})`);
275	    }
276	    if (fs.existsSync(backup)) {
277	      const existing = fs.readFileSync(backup);
278	      if (!existing.equals(bytes)) {
279	        throw new Error(
280	          `Operation ${id}: cannot migrate the operation record because ${backup} already exists with different content. ` +
281	            `Move it aside to continue, or restore it to read the record with the build that wrote it.`,
282	        );
283	      }
284	      return;
285	    }
286	    writePrivateFile(backup, bytes, { durable: true, mode: 0o600 });
287	  }
288	}
289	
290	const OPERATION_LOCK_UNREADABLE_GRACE_MS = 30_000;
291	
292	/** Test seam: runs between judging a lock stale and taking it over. Not an extension point. */
293	export const operationLockSeams: { afterStaleCheck?: () => void } = {};
294	
295	export class OperationLockedError extends Error {
296	  constructor(message: string) {
297	    super(message);
298	    this.name = "OperationLockedError";
299	  }
300	}
301	
302	/** Re-key legacy short hashes without changing which resources share an account-scoped condition. */
303	export function migrateLegacyAccountIdentities(
304	  operation: DurableOperationState,
305	  identity: OperationAccountIdentity,
306	): DurableOperationState {
307	  // Schema-1 records do not retain whether an old 12-hex account value came
308	  // from the CLI label or the former credential hash. Preserve explicitly
309	  // marked labels; migrate unmarked 12-hex values as legacy credential IDs.
310	  const explicitAccounts = new Set(
311	    operation.resources.filter((resource) => resource.accountIdentitySource === "explicit" && resource.account).map((resource) => resource.account!),
312	  );
313	  const explicitAccountConditionKeys = new Set(
314	    operation.resources
315	      .filter((resource) => resource.accountIdentitySource === "explicit" && resource.account)
316	      .map((resource) => `${resource.provider}|account|${resource.account}`),
317	  );
318	  const migrated = new Map<string, string>();
319	  const replacement = (value: string): string => {
320	    if (explicitAccounts.has(value) || !isLegacyCredentialFingerprint(value)) return value;
321	    let mapped = migrated.get(value);
322	    if (!mapped) {
323	      mapped = identity.migrateLegacy(value, operation.id);
324	      migrated.set(value, mapped);
325	    }
326	    return mapped;
327	  };
328	
329	  for (const resource of operation.resources) {
330	    if (resource.account) resource.account = replacement(resource.account);
331	  }
332	  for (const condition of operation.conditions) {
333	    if (condition.scope !== "account") continue;
334	    // Account labels are arbitrary strings and may themselves contain `|account|`; preserve the full key for
335	    // explicitly labeled resources instead of parsing the final delimiter as a structural boundary.
336	    if (explicitAccountConditionKeys.has(condition.key)) continue;
337	    const marker = "|account|";
338	    const markerAt = condition.key.lastIndexOf(marker);
339	    if (markerAt < 0) continue;
340	    const oldAccount = condition.key.slice(markerAt + marker.length);
341	    const newAccount = replacement(oldAccount);
342	    if (newAccount !== oldAccount) condition.key = `${condition.key.slice(0, markerAt + marker.length)}${newAccount}`;
343	  }
344	  return operation;
345	}
346	
347	function processAlive(pid: number): boolean {
348	  try {
349	    process.kill(pid, 0);
350	    return true;
351	  } catch (err: any) {
352	    return err?.code === "EPERM";
353	  }
354	}
