66	export function readJournal(prefix: string): UpgradeJournalEntry | null {
67	  const journalPath = getJournalPath(prefix);
68	  if (!fs.existsSync(journalPath)) return null;
69	  try {
70	    if (!fs.lstatSync(journalPath).isFile() || fs.realpathSync(journalPath) !== path.resolve(journalPath)) return null;
71	    const raw = fs.readFileSync(journalPath, "utf8");
72	    const data = JSON.parse(raw);
73	    if (isValidJournal(data, prefix)) {
74	      return data as UpgradeJournalEntry;
75	    }
76	  } catch {}
77	  return null;
78	}
