80	function isValidJournal(value: any, prefix: string): value is UpgradeJournalEntry {
81	  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
82	  const states: JournalState[] = ["idle", "preparing", "downloading", "staged", "switching", "switched", "verified", "complete", "recovery_required", "rolled_back"];
83	  const root = path.resolve(prefix);
84	  const libRoot = path.join(root, "lib", "nexus");
85	  const expectedBin = path.join(root, "bin", "nexus");
86	  const versionDir = (version: unknown) => typeof version === "string" && /^[v]?[0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?$/.test(version)
87	    ? path.join(libRoot, version)
88	    : "";
89	  const sourceDir = versionDir(value.sourceVersion);
90	  const targetDir = versionDir(value.targetVersion);
91	  const expectedPath = (actual: unknown, expected: string) => typeof actual === "string" && expected !== "" && path.resolve(actual) === expected;
92	  const isoDate = (date: unknown) => typeof date === "string" && Number.isFinite(Date.parse(date));
93	
94	  if (value.formatVersion !== 1 || typeof value.id !== "string" || value.id.length < 1 || value.id.length > 128 ||
95	      !states.includes(value.state) || !sourceDir || !targetDir ||
96	      !expectedPath(value.prefix, root) || !expectedPath(value.sourceInstallDir, sourceDir) ||
97	      !expectedPath(value.targetInstallDir, targetDir) || !expectedPath(value.sourceSymlinkTarget, path.join(sourceDir, "bin", "nexus")) ||
98	      !expectedPath(value.binPath, expectedBin) || !isoDate(value.startedAt) || !isoDate(value.updatedAt)) return false;
99	
100	  if (!/^[A-Za-z0-9._-]+$/.test(value.id)) return false;
101	  for (const [field, name] of [["replacementBackupDir", `.rollback-${value.id}`], ["displacedTargetDir", `.failed-${value.id}`]]) {
102	    if (value[field] !== undefined && !expectedPath(value[field], path.join(libRoot, name))) return false;
103	  }
104	  if (sourceDir === targetDir && !value.replacementBackupDir) return false;
105	  if (value.stagingDir !== undefined) {
106	    if (typeof value.stagingDir !== "string" || path.dirname(path.resolve(value.stagingDir)) !== libRoot ||
107	        !/^\.tmp-upgrade-[A-Za-z0-9._-]{1,128}$/.test(path.basename(value.stagingDir))) return false;
108	  }
109	  if (value.configBackupPath !== undefined) {
110	    const backups = path.join(process.env.HOME || "", ".config", "nexus", "backups");
111	    if (typeof value.configBackupPath !== "string" || path.dirname(path.resolve(value.configBackupPath)) !== backups ||
112	        !/^config\.env\.bak\.[A-Za-z0-9T_.-]+$/.test(path.basename(value.configBackupPath))) return false;
113	  }
114	  if (value.stateBackupDir !== undefined) {
115	    const backups = path.join(stateRoot(process.env.HOME || ""), "backups");
116	    if (typeof value.stateBackupDir !== "string" || path.dirname(path.resolve(value.stateBackupDir)) !== backups ||
117	        !/^state-backup-[A-Za-z0-9T_.-]+$/.test(path.basename(value.stateBackupDir))) return false;
118	  }
119	  return true;
120	}
