122	export function writeJournal(prefix: string, entry: UpgradeJournalEntry): void {
123	  const journalPath = getJournalPath(prefix);
124	  const dir = path.dirname(journalPath);
125	  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
126	  const tmp = `${journalPath}.tmp.${process.pid}.${Date.now()}`;
127	  fs.writeFileSync(tmp, JSON.stringify(entry, null, 2), { mode: 0o600 });
128	  const fd = fs.openSync(tmp, "r");
129	  try { fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
130	  fs.renameSync(tmp, journalPath);
131	  syncDirectory(dir);
132	}
