134	export function clearJournal(prefix: string): void {
135	  const journalPath = getJournalPath(prefix);
136	  if (fs.existsSync(journalPath)) {
137	    try {
138	      fs.unlinkSync(journalPath);
139	    } catch {}
140	  }
141	}
