143	/**
144	 * Creates pre-migration backups of configuration and durable state.
145	 * Files are created with strict 0600 permissions in 0700 directories.
146	 */
147	export function createPreMigrationBackup(
148	  homeDir: string = process.env.HOME || "",
149	  onProgress?: (progress: BackupProgress) => void,
150	): BackupResult {
151	  const result: BackupResult = {};
152	  const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
153	  let filesCopied = 0;
154	  let bytesCopied = 0;
155	  let lastProgressAt = Date.now();
156	  let lastReportedFiles = 0;
157	  let lastReportedBytes = 0;
158	  const reportProgress = () => {
159	    const now = Date.now();
160	    if (now - lastProgressAt >= 5_000 || (filesCopied - lastReportedFiles >= 1_024 && now - lastProgressAt >= 2_000)) {
161	      onProgress?.({ filesCopied, bytesCopied });
162	      lastProgressAt = now;
163	      lastReportedFiles = filesCopied;
164	      lastReportedBytes = bytesCopied;
165	    }
166	  };
167	  const observer = {
168	    bytesCopied: (bytes: number) => {
169	      bytesCopied += bytes;
170	      reportProgress();
171	    },
172	    fileCopied: () => {
173	      filesCopied += 1;
174	      reportProgress();
175	    },
176	  };
177	
178	  // 1. Config backup
179	  const configEnv = path.join(homeDir, ".config", "nexus", "config.env");
180	  if (fs.existsSync(configEnv)) {
181	    if (!fs.lstatSync(configEnv).isFile() || fs.realpathSync(configEnv) !== path.resolve(configEnv)) throw new Error("Configuration backup source is redirected");
182	    const backupDir = path.join(homeDir, ".config", "nexus", "backups");
183	    const backupDirExisted = fs.existsSync(backupDir);
184	    fs.mkdirSync(backupDir, { recursive: true, mode: 0o700 });
185	    if (fs.realpathSync(backupDir) !== path.resolve(backupDir)) throw new Error("Configuration backup directory is redirected");
186	    if (!backupDirExisted) syncDirectory(path.dirname(backupDir));
187	    const backupFile = path.join(backupDir, `config.env.bak.${timestamp}`);
188	    copyPrivateFileDurably(configEnv, backupFile, true, observer.bytesCopied);
189	    observer.fileCopied();
190	    result.configBackupPath = backupFile;
191	  }
192	
193	  // 2. State backup
194	  const stateDir = path.join(stateRoot(homeDir),);
195	  if (fs.existsSync(stateDir)) {
196	    const stateBackupsDir = path.join(stateDir, "backups");
197	    const stateBackupsDirExisted = fs.existsSync(stateBackupsDir);
198	    fs.mkdirSync(stateBackupsDir, { recursive: true, mode: 0o700 });
199	    if (fs.realpathSync(stateBackupsDir) !== path.resolve(stateBackupsDir)) throw new Error("State backup directory is redirected");
200	    if (!stateBackupsDirExisted) syncDirectory(stateDir);
201	    const backupDest = path.join(stateBackupsDir, `state-backup-${timestamp}`);
202	    // Each timestamped backup is a single immutable attempt. Never merge into
203	    // an existing directory left by a collision or interrupted prior attempt.
204	    fs.mkdirSync(backupDest, { mode: 0o700 });
205	    syncDirectory(stateBackupsDir);
206	
207	    // Snapshot all durable state, not just its index. Backup directories are
208	    // excluded to avoid recursion; symbolic links are refused rather than read.
209	    withDurableStoreGuards(homeDir, () => copyPrivateTree(stateDir, path.join(backupDest, "state"), new Set(["backups", "restore-control", STATE_RESTORE_PENDING_FILE]), observer));
210	    const configDir = path.join(homeDir, ".config", "nexus");
211	    if (fs.existsSync(configDir)) copyPrivateTree(configDir, path.join(backupDest, "config"), new Set(["backups", STATE_RESTORE_PENDING_FILE]), observer);
212	    const metadataPath = path.join(backupDest, "backup.json");
213	    const metadataFd = fs.openSync(metadataPath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | (fs.constants.O_NOFOLLOW ?? 0), 0o600);
214	    try {
215	      fs.writeFileSync(metadataFd, JSON.stringify({ formatVersion:1, kind:"nexus-state-config", createdAt:new Date().toISOString() }));
216	      fs.fchmodSync(metadataFd, 0o600);
217	      fs.fsyncSync(metadataFd);
218	    } finally { fs.closeSync(metadataFd); }
219	    syncDirectory(backupDest);
220	
221	    result.stateBackupDir = backupDest;
222	  }
223	
224	  if (filesCopied > lastReportedFiles || bytesCopied > lastReportedBytes) onProgress?.({ filesCopied, bytesCopied });
225	
226	  return result;
227	}
