229	/**
230	 * Restores configuration from a previous backup file.
231	 */
232	export function restoreConfigBackup(backupPath: string, homeDir: string = process.env.HOME || "", onError?: (error: unknown) => void): boolean {
233	  try {
234	    const resolved = path.resolve(backupPath);
235	    if (fs.realpathSync(resolved) !== resolved) return false;
236	    const configRoot = path.join(homeDir, ".config", "nexus");
237	    if (fs.lstatSync(resolved).isDirectory()) {
238	      if (path.dirname(resolved) !== path.join(stateRoot(homeDir), "backups") || !/^state-backup-[A-Za-z0-9T_.-]+$/.test(path.basename(resolved))) return false;
239	      const metadata = JSON.parse(fs.readFileSync(path.join(resolved, "backup.json"), "utf8"));
240	      if (metadata.formatVersion !== 1 || metadata.kind !== "nexus-state-config") return false;
241	      // Validate the entire source tree before touching live configuration/state.
242	      validatePrivateTree(resolved);
243	      const state = path.join(resolved, "state");
244	      const config = path.join(resolved, "config");
245	      const sources = [];
246	      if (fs.existsSync(state)) sources.push({ store: "state" as const, source: state, mode: "tree" as const });
247	      if (fs.existsSync(config)) sources.push({ store: "config" as const, source: config, mode: "tree" as const });
248	      return sources.length > 0 && restoreFromSources(homeDir, sources, onError);
249	    }
250	    // Legacy plain config backups are recognized by their canonical location
251	    // and name. Archives and arbitrary files must never become config.env.
252	    if (path.dirname(resolved) !== path.join(configRoot, "backups") || !/^config\.env\.bak\.[A-Za-z0-9T_.-]+$/.test(path.basename(resolved)) || !fs.lstatSync(resolved).isFile()) return false;
253	    return restoreFromSources(homeDir, [{ store:"config", source:resolved, mode:"file" }], onError);
254	  } catch (error) {
255	    try { onError?.(error); } catch {}
256	    return false;
257	  }
258	}
259	/** Keep permanent guard inodes even when rolling back to a backup without that store. */
260	/** New clients serialize task/session multi-file snapshots in a fixed lock order. */
261	function withDurableStoreGuards<T>(homeDir: string, callback: () => T): T {
262	  const tasks = path.join(stateRoot(homeDir), "tasks");
263	  const sessions = path.join(stateRoot(homeDir), "sessions");
264	  for (const directory of [tasks, sessions]) {
265	    fs.mkdirSync(directory, { recursive: true, mode: 0o700 });
266	    if (fs.realpathSync(directory) !== path.resolve(directory)) throw new Error("State store is redirected");
267	  }
268	  return withStateStoreGuard(tasks, () => withStateStoreGuard(sessions, callback));
269	}
270	
271	function validatePrivateTree(source: string): void {
272	  if (fs.realpathSync(source) !== path.resolve(source)) throw new Error("Backup path is redirected");
273	  const stat = fs.lstatSync(source);
274	  if (stat.isSymbolicLink() || (!stat.isDirectory() && !stat.isFile())) throw new Error("Backup contains unsupported files");
275	  if (stat.isDirectory()) for (const name of fs.readdirSync(source)) validatePrivateTree(path.join(source, name));
276	}
277	function copyPrivateTree(
278	  source: string,
279	  destination: string,
280	  excluded = new Set<string>(),
281	  observer?: { bytesCopied: (bytes: number) => void; fileCopied: () => void },
282	): void {
283	  validatePrivateTreeExcept(source, excluded);
284	  const existed = fs.existsSync(destination);
285	  fs.mkdirSync(destination, { recursive:true, mode:0o700 });
286	  if (fs.realpathSync(destination) !== path.resolve(destination)) throw new Error("Backup destination is redirected");
287	  if (!existed) syncDirectory(path.dirname(destination));
288	  fs.chmodSync(destination, 0o700);
289	  for (const entry of fs.readdirSync(source, { withFileTypes:true })) {
290	    if (excluded.has(entry.name) || entry.name === STATE_STORE_GUARD_FILE || entry.name === STATE_RESTORE_PENDING_FILE) continue;
291	    const from = path.join(source, entry.name), to = path.join(destination, entry.name);
292	    if (entry.isDirectory()) copyPrivateTree(from, to, new Set(), observer);
293	    else {
294	      copyPrivateFileDurably(from, to, false, observer?.bytesCopied);
295	      observer?.fileCopied();
296	    }
297	  }
298	  // File contents are fsynced individually. Batch directory-entry durability
299	  // once per directory instead of forcing a journal commit for every file.
300	  syncDirectory(destination);
301	}
302	
303	/** A backup is not returned to the journal until its bytes and directory entry are durable. */
304	function copyPrivateFileDurably(
305	  source: string,
306	  destination: string,
307	  syncParentOnSuccess = true,
308	  onBytesCopied?: (bytes: number) => void,
309	): number {
310	  const sourcePath = path.resolve(source);
311	  if (fs.realpathSync(sourcePath) !== sourcePath) throw new Error("Backup source is redirected");
312	  const sourceFd = fs.openSync(sourcePath, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
313	  let destinationFd: number | undefined;
314	  let destinationCreated = false;
315	  try {
316	    const opened = fs.fstatSync(sourceFd);
317	    const current = fs.lstatSync(sourcePath);
318	    if (!opened.isFile() || current.isSymbolicLink() || opened.dev !== current.dev || opened.ino !== current.ino) {
319	      throw new Error("Backup source changed while opening");
320	    }
321	    destinationFd = fs.openSync(destination, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | (fs.constants.O_NOFOLLOW ?? 0), 0o600);
322	    destinationCreated = true;
323	    const buffer = Buffer.alloc(64 * 1024);
324	    let position = 0;
325	    while (true) {
326	      const count = fs.readSync(sourceFd, buffer, 0, buffer.length, position);
327	      if (count === 0) break;
328	      let written = 0;
329	      while (written < count) {
330	        const chunkWritten = fs.writeSync(destinationFd, buffer, written, count - written);
331	        written += chunkWritten;
332	        onBytesCopied?.(chunkWritten);
333	      }
334	      position += count;
335	    }
336	    fs.fchmodSync(destinationFd, 0o600);
337	    fs.fsyncSync(destinationFd);
338	    fs.closeSync(destinationFd);
339	    destinationFd = undefined;
340	    if (syncParentOnSuccess) syncDirectory(path.dirname(destination));
341	    return position;
342	  } catch (error) {
343	    if (destinationFd !== undefined) try { fs.closeSync(destinationFd); } catch {}
344	    if (destinationCreated) {
345	      try { fs.unlinkSync(destination); syncDirectory(path.dirname(destination)); } catch {}
346	    }
347	    throw error;
348	  } finally { fs.closeSync(sourceFd); }
349	}
350	function validatePrivateTreeExcept(source: string, excluded: Set<string>): void {
351	  if (fs.realpathSync(source) !== path.resolve(source) || !fs.lstatSync(source).isDirectory()) throw new Error("State root is redirected");
352	  for (const entry of fs.readdirSync(source)) if (!excluded.has(entry)) validatePrivateTree(path.join(source, entry));
353	}
