361	/**
362	 * Permanent kernel-owned guard that serializes stale-lock reclamation between
363	 * concurrent processes. The guard is a regular file that is never unlinked or
364	 * replaced; mutual exclusion comes from an advisory flock held on the open file
365	 * description for the whole reclaim section. The kernel releases the lock when
366	 * the last referring descriptor closes, so a reclaimer killed by SIGKILL or a
367	 * power loss cannot wedge later upgrades, and no recursive takeover of a stale
368	 * gate directory is ever performed.
369	 */
370	export type ReclaimGuard = FileGuard;
371	
372	const FLOCK_UTILITY = "/usr/bin/flock";
373	
374	/**
375	 * Acquires the reclaim guard. Returns null on contention (another live
376	 * reclaimer holds the kernel lock) and throws on any unsupported or failed
377	 * prerequisite so callers fail closed instead of proceeding unserialized.
378	 * The utility path is injectable so tests can demonstrate fail-closed
379	 * behavior without modifying the real system utility.
380	 */
381	export function acquireReclaimGuard(guardPath: string, flockUtility: string = FLOCK_UTILITY): ReclaimGuard | null {
382	  return acquireFileGuard(guardPath, { utility: flockUtility, label: "Reclaim guard" });
383	}
384	
385	export function releaseReclaimGuard(guard: ReclaimGuard | null): void {
386	  releaseFileGuard(guard);
387	}
