389	/**
390	 * Idempotent crash recovery: inspects journal and restores working installation or finalizes transition.
391	 */
392	export function recoverUpgrade(prefix: string, options: { forceRollback?: boolean; timeoutMs?: number; lockHeld?: boolean; onStaleLockObserved?: () => void } = {}): RecoveryOutcome {
393	  const journalPath = getJournalPath(prefix);
394	  const journal = readJournal(prefix);
395	  if (!journal && !fs.existsSync(journalPath)) return { recovered:false, action:"none", details:"No interrupted upgrade found in journal." };
396	  if (journal && ["idle", "complete", "rolled_back"].includes(journal.state) && !options.forceRollback) return { recovered:false, action:"none", details:"No interrupted upgrade found in journal." };
397	  const lock = path.join(prefix, "lib", "nexus", ".upgrade.lock");
398	  let owned = false, ownedIno: number | undefined;
399	  const token = `${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
400	  const inProgress: RecoveryOutcome = { recovered:false, action:"upgrade_in_progress", details:"An upgrade transaction is currently in progress." };
401	  const acquire = () => {
402	    const fd = fs.openSync(lock, "wx", 0o600);
403	    try { fs.writeFileSync(fd, JSON.stringify({ pid:process.pid, token })); fs.fsyncSync(fd); ownedIno = fs.fstatSync(fd).ino; }
404	    finally { fs.closeSync(fd); }
405	    owned = true;
406	  };
407	  try {
408	    if (fs.existsSync(lock)) {
409	      if (!isRealFile(lock)) throw new Error("Upgrade lock is redirected");
410	      const staleStat = fs.lstatSync(lock), staleIno = staleStat.ino;
411	      const holder = JSON.parse(fs.readFileSync(lock, "utf8"));
412	      if (!Number.isSafeInteger(holder.pid) || holder.pid < 1) throw new Error("Upgrade lock is invalid");
413	      if (holder.pid === process.pid && !options.lockHeld) return inProgress;
414	      if (holder.pid !== process.pid) {
415	        try { process.kill(holder.pid, 0); return inProgress; }
416	        catch (error:any) { if (error.code === "EPERM") return inProgress; if (error.code !== "ESRCH") throw error; }
417	        options.onStaleLockObserved?.();
418	        const guardPath = `${lock}.guard`;
419	        let guard = acquireReclaimGuard(guardPath);
420	        if (!guard) {
421	          // A live reclaimer holds the kernel guard: give it a moment, then
422	          // re-check whether it took over the lock before reporting progress.
423	          Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 200);
424	          const current = fs.lstatSync(lock, { throwIfNoEntry:false });
425	          if (!current || current.ino !== staleIno) return inProgress;
426	          guard = acquireReclaimGuard(guardPath);
427	          if (!guard) return { recovered:false, action:"upgrade_in_progress", details:`An upgrade transaction is currently in progress (reclaim guard: ${guardPath}).` };
428	        }
429	        try {
430	          const currentStat = fs.lstatSync(lock, { throwIfNoEntry:false });
431	          if (!currentStat || currentStat.ino !== staleIno) return inProgress;
432	          try {
433	            if (JSON.parse(fs.readFileSync(lock, "utf8")).pid !== holder.pid) return inProgress;
434	          } catch { return inProgress; }
435	          fs.unlinkSync(lock);
436	          acquire();
437	        } finally { releaseReclaimGuard(guard); }
438	      }
439	    }
440	    if (!owned && !fs.existsSync(lock) && fs.existsSync(path.dirname(lock))) {
441	      try { acquire(); } catch (error:any) { if (error.code === "EEXIST") return inProgress; throw error; }
442	    }
443	    return recoverUpgradeLocked(prefix, options);
444	  } catch (error:any) { return { recovered:false, action:"manual_intervention", details:error.message }; }
445	  finally {
446	    if (owned) try {
447	      const current = fs.lstatSync(lock, { throwIfNoEntry:false });
448	      if (current?.ino === ownedIno && JSON.parse(fs.readFileSync(lock, "utf8")).token === token) fs.unlinkSync(lock);
449	    } catch {}
450	  }
451	}
452	function recoverUpgradeLocked(prefix: string, options: { forceRollback?: boolean; timeoutMs?: number; lockHeld?: boolean } = {}): RecoveryOutcome {
453	  const journalPath = getJournalPath(prefix);
454	  const journal = readJournal(prefix);
455	  const failed = (details: string): RecoveryOutcome => ({ recovered:false, action:"manual_intervention", details });
456	  if (!journal && fs.existsSync(journalPath)) return failed("Upgrade journal failed schema or path validation; no recovery action was taken.");
457	  if (!journal || (["idle", "complete", "rolled_back"].includes(journal.state) && !options.forceRollback)) return { recovered:false, action:"none", details:"No interrupted upgrade found in journal." };
458	  const libRoot = path.join(path.resolve(prefix), "lib", "nexus");
459	  if (!isRealDirectory(libRoot) || !isRealDirectory(path.dirname(journal.binPath))) return failed("Upgrade recovery roots are not real contained directories; no recovery action was taken.");
460	  for (const directory of [journal.sourceInstallDir, journal.targetInstallDir, journal.replacementBackupDir, journal.displacedTargetDir, journal.stagingDir]) {
461	    if (directory && fs.existsSync(directory) && !isRealDirectory(directory)) return failed("A recovery path is not a contained real directory; no recovery action was taken.");
462	    // lstat also detects dangling symlinks, which existsSync deliberately ignores.
463	    if (directory) { try { if (fs.lstatSync(directory).isSymbolicLink()) return failed("A recovery path is a symlink; no recovery action was taken."); } catch (error: any) { if (error.code !== "ENOENT") return failed(error.message); } }
464	  }
465	  try {
466	    if (!options.forceRollback && journal.state === "verified" && verifyInstalledRuntime(journal.targetInstallDir, journal.targetVersion, options.timeoutMs).healthy) {
467	      atomicSymlinkSwap(path.join(journal.targetInstallDir, "bin", "nexus"), journal.binPath);
468	      journal.state = "complete";
469	      journal.updatedAt = new Date().toISOString();
470	      writeJournal(prefix, journal);
471	      return { recovered:true, action:"finalized", details:`Finalized verified release ${journal.targetVersion}.` };
472	    }
473	    // The old package is kept outside disposable staging. The journal records its
474	    // identity BEFORE the first rename, covering crashes on either side of it.
475	    const early = ["preparing", "downloading", "staged"].includes(journal.state);
476	    const sameVersion = journal.sourceInstallDir === journal.targetInstallDir;
477	    const saved = journal.replacementBackupDir;
478	    if (saved && fs.existsSync(saved)) {
479	      if (!verifyInstalledRuntime(saved, sameVersion ? journal.sourceVersion : journal.targetVersion, options.timeoutMs).healthy && sameVersion) throw new Error("Preserved source package failed runtime validation; retained for manual intervention");
480	      if (fs.existsSync(journal.targetInstallDir)) {
481	        if (!journal.displacedTargetDir || fs.existsSync(journal.displacedTargetDir)) throw new Error("Cannot displace failed target safely; all packages retained");
482	        fs.renameSync(journal.targetInstallDir, journal.displacedTargetDir);
483	        syncDirectory(libRoot);
484	      }
485	      fs.renameSync(saved, journal.targetInstallDir);
486	      syncDirectory(libRoot);
487	    }
488	    const health = verifyInstalledRuntime(journal.sourceInstallDir, journal.sourceVersion, options.timeoutMs);
489	    if (!health.healthy) throw new Error(`source launcher/runtime is unverified: ${health.error}`);
490	    atomicSymlinkSwap(journal.sourceSymlinkTarget, journal.binPath);
491	    journal.state = "rolled_back";
492	    journal.updatedAt = new Date().toISOString();
493	    delete journal.error;
494	    writeJournal(prefix, journal);
495	    // Never delete staging before successful source restoration. Failed packages
496	    // and the original backup remain available if any step above fails.
497	    if (journal.stagingDir && fs.existsSync(journal.stagingDir)) fs.rmSync(journal.stagingDir, { recursive:true, force:true });
498	    return { recovered:true, action:early ? "cleaned_up" : "rolled_back", details:`Restored verified source release ${journal.sourceVersion}.` };
499	  } catch (error: any) {
500	    journal.state = "recovery_required";
501	    journal.error = `Manual intervention required: ${error.message}`;
502	    journal.updatedAt = new Date().toISOString();
503	    try { writeJournal(prefix, journal); } catch {}
504	    return failed(journal.error);
505	  }
506	}
507	
508	/** Flush rename boundaries as well as the journal before reporting success. */
509	export function syncDirectory(directory: string): void {
510	  const fd = fs.openSync(directory, "r");
511	  try { fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
512	}
513	
514	function isRealDirectory(directory: string): boolean {
515	  try {
516	    const absolute = path.resolve(directory);
517	    const stat = fs.lstatSync(absolute);
518	    return stat.isDirectory() && !stat.isSymbolicLink() && fs.realpathSync(absolute) === absolute;
519	  } catch {
520	    return false;
521	  }
522	}
523	
524	function isRealFile(filePath: string): boolean {
525	  try {
526	    const absolute = path.resolve(filePath);
527	    const stat = fs.lstatSync(absolute);
528	    return stat.isFile() && !stat.isSymbolicLink() && fs.realpathSync(absolute) === absolute;
529	  } catch {
530	    return false;
531	  }
532	}
533	
534	function atomicSymlinkSwap(targetFile: string, linkPath: string): void {
535	  const binDir = path.dirname(linkPath);
536	  fs.mkdirSync(binDir, { recursive: true });
537	  const token = `${process.pid}.${Date.now()}.${randomUUID()}`;
538	  const tmpLink = path.join(binDir, `.nexus-link-recovery.${token}`);
539	  const displacedLink = `${linkPath}.nexus-recovery-previous`;
540	  const priorDisplacement = fs.lstatSync(displacedLink, { throwIfNoEntry:false });
541	  if (priorDisplacement) {
542	    const current = fs.lstatSync(linkPath, { throwIfNoEntry:false });
543	    if (!current) {
544	      // A previous process stopped after moving the launcher aside. Restore it
545	      // exclusively before retrying, including when the displaced entry is a
546	      // raced regular file that the previous process had not yet inspected.
547	      fs.linkSync(displacedLink, linkPath);
548	      syncDirectory(binDir);
549	      fs.unlinkSync(displacedLink);
550	      syncDirectory(binDir);
551	    } else if (current.dev === priorDisplacement.dev && current.ino === priorDisplacement.ino) {
552	      // A prior process restored the displaced entry by exclusive hard link
553	      // and stopped before unlinking the backup name. This also covers regular
554	      // launchers and symlinks whose old target differs from this retry.
555	      fs.unlinkSync(displacedLink);
556	      syncDirectory(binDir);
557	    } else if (priorDisplacement.isSymbolicLink() && current.isSymbolicLink() && fs.readlinkSync(linkPath) === targetFile) {
558	      // The new launcher was installed and only backup cleanup was interrupted.
559	      fs.unlinkSync(displacedLink);
560	      syncDirectory(binDir);
561	    } else {
562	      throw new Error("An interrupted launcher recovery needs manual intervention; preserving both entries");
563	    }
564	  }
565	  const launcher = fs.lstatSync(linkPath, { throwIfNoEntry:false });
566	  if (launcher && !launcher.isSymbolicLink()) throw new Error("Upgrade launcher is not a symbolic link; refusing to replace it");
567	  try {
568	    fs.symlinkSync(targetFile, tmpLink);
569	    if (launcher) {
570	      // Move the old entry aside, then install with link(2), which fails with
571	      // EEXIST instead of replacing a regular file created in the check/swap
572	      // window. Verify what was moved before treating it as our old symlink.
573	      fs.renameSync(linkPath, displacedLink);
574	      syncDirectory(binDir);
575	      const displaced = fs.lstatSync(displacedLink);
576	      if (!displaced.isSymbolicLink() || displaced.dev !== launcher.dev || displaced.ino !== launcher.ino) {
577	        fs.linkSync(displacedLink, linkPath);
578	        syncDirectory(binDir);
579	        fs.unlinkSync(displacedLink);
580	        syncDirectory(binDir);
581	        throw new Error("Upgrade launcher changed during recovery; refusing to replace it");
582	      }
583	    }
584	    // Hard-linking the temporary symlink creates the destination exclusively;
585	    // unlike rename, it cannot clobber an entry raced into place.
586	    fs.linkSync(tmpLink, linkPath);
587	    syncDirectory(binDir);
588	    fs.unlinkSync(tmpLink);
589	    if (launcher) fs.unlinkSync(displacedLink);
590	    syncDirectory(binDir);
591	  } catch (err: any) {
592	    if (fs.existsSync(displacedLink) && !fs.existsSync(linkPath)) {
593	      try { fs.linkSync(displacedLink, linkPath); syncDirectory(binDir); fs.unlinkSync(displacedLink); syncDirectory(binDir); } catch {}
594	    }
595	    try {
596	      fs.unlinkSync(tmpLink);
597	    } catch {}
598	    throw err;
599	  }
600	}
